(function(){'use strict';if(typeof window==='undefined')return;if(window.MwHaptics)return;function hapticsPlugin(){if(!window.Capacitor||!window.Capacitor.Plugins)return null;return window.Capacitor.Plugins.Haptics||null}
var vibratePatterns={tap:20,selection:10,success:[20,40,20],warning:60,error:[40,60,40,60,40],};function webVibrate(kind){if(!navigator.vibrate)return;var p=vibratePatterns[kind];if(p===undefined)return;try{navigator.vibrate(p)}catch(_){}}
function nativeHaptic(kind){var h=hapticsPlugin();if(!h)return!1;try{switch(kind){case 'tap':h.impact({style:'Light'});return!0;case 'selection':if(h.selectionStart){h.selectionStart();h.selectionEnd&&h.selectionEnd()}else{h.impact({style:'Light'})}
return!0;case 'success':if(h.notification){h.notification({type:'SUCCESS'})}else{h.impact({style:'Medium'})}
return!0;case 'warning':if(h.notification){h.notification({type:'WARNING'})}else{h.impact({style:'Medium'})}
return!0;case 'error':if(h.notification){h.notification({type:'ERROR'})}else{h.impact({style:'Heavy'})}
return!0}}catch(e){}
return!1}
function fire(kind){try{if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches){return}}catch(_){}
if(nativeHaptic(kind))return;webVibrate(kind)}
window.MwHaptics={tap:function(){fire('tap')},selection:function(){fire('selection')},success:function(){fire('success')},warning:function(){fire('warning')},error:function(){fire('error')},fire:fire,};function installAutoWire(){document.addEventListener('click',function(e){var el=e.target;for(var i=0;i<4&&el&&el!==document;i++){if(el.dataset&&el.dataset.haptic){fire(el.dataset.haptic);return}
el=el.parentNode}},!0)}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',installAutoWire)}else{installAutoWire()}}())